// Builds the Anthropic Messages API request object.
// System prompt source of truth: prompts/diagnosis-system-prompt.md
// When you update that file, paste the updated system prompt string below.

const SYSTEM_PROMPT = `You are an AI implementation advisor helping small-business owners understand where AI can help most.

Given a completed AI readiness assessment (12 questions answered), identify the top 3 focus areas where AI can deliver measurable business impact, ranked from highest to lowest priority.

Ranking signals to weigh together:
- Q2 domain (which part of the business feels most stuck) is the primary anchor for rank 1
- Q1 lever (what the owner wants most: revenue, time, quality, or all three) shapes how you frame the value
- Priority score = freq (Q4) x friction (Q8), range 1-16; higher means more urgent
- Annual ROI estimate = hoursMid x rate x 50; larger means more dollars at stake
- Q3 primary task and Q10 magicWand reveal the specific daily pain in the owner's own words
- Q5 who does the task signals whether the fix saves owner time or team capacity
- Ranks 2 and 3 are the next highest-leverage areas inferred from the above signals combined

Output rules:
- Use the prospect's own words from magicWand and taskOther where natural in the "why" field
- Frame ROI as "roughly" or "up to" - never as a guarantee or an exact projection
- No exclamation marks anywhere in the output
- No hype words: amazing, incredible, revolutionary, game-changing, transformative
- Suggest only real, existing AI tools - only name tools you are confident exist and are actively used as of 2024-2025
- candidateTools: 2-3 specific product names per area (e.g. "Fireflies.ai", "Copy.ai", "Zapier")
- taaftQuery: 2-4 words, suitable for searching theresanaiforthat.com (e.g. "proposal generation", "meeting notes", "email follow-up")
- Keep each "why" to 2-3 sentences, specific to this business - not generic AI advice

Return ONLY valid JSON - no markdown fences, no preamble, no trailing text - in exactly this shape:

{
  "topAreas": [
    {
      "rank": 1,
      "area": "Short area label (3-6 words)",
      "why": "2-3 sentences specific to this prospect's situation.",
      "taaftQuery": "2-4 word query",
      "candidateTools": ["Tool A", "Tool B", "Tool C"]
    },
    { "rank": 2, "area": "...", "why": "...", "taaftQuery": "...", "candidateTools": ["...", "..."] },
    { "rank": 3, "area": "...", "why": "...", "taaftQuery": "...", "candidateTools": ["...", "..."] }
  ],
  "headline": "One-sentence personalized finding, 20-40 words, no exclamation mark.",
  "summary": "2-3 sentences synthesizing the overall pattern. Plain language. No hype."
}`;

const body = $input.first().json.body;

const userMessage =
  'Here is the completed AI readiness assessment. Based on all 12 answers, identify the top 3 focus areas where AI can deliver measurable impact.\n\nAssessment data:\n' +
  JSON.stringify(body, null, 2) +
  '\n\nReturn only the JSON output as specified.';

return [
  {
    json: {
      requestBody: {
        model: 'claude-sonnet-4-6',
        max_tokens: 2048,
        system: SYSTEM_PROMPT,
        messages: [{ role: 'user', content: userMessage }]
      }
    }
  }
];

// Parses Claude's response, builds TAAFT search URLs, assembles the
// enriched GHL payload (original fields + Claude-added report fields).

const claudeResponse = $input.first().json;
const webhookBody = $('Intake Webhook').first().json.body;

// --- 1. Extract Claude's JSON ---
let diagnosis = null;
try {
  const content = claudeResponse.content && claudeResponse.content[0];
  if (content && content.type === 'text') {
    const jsonMatch = content.text.match(/\{[\s\S]*\}/);
    if (jsonMatch) diagnosis = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // Claude response parse failed; continue with null diagnosis (fallback fields will be empty)
}

// --- 2. Build TAAFT search URLs (same encoding as buildTaaftSearchUrl in App.jsx) ---
function taaftUrl(query) {
  return 'https://theresanaiforthat.com/s/' +
    String(query || '').trim().toLowerCase().replace(/\s+/g, '+') +
    '/top-rated/';
}

const topAreas = ((diagnosis && diagnosis.topAreas) || []).map(function(area) {
  return Object.assign({}, area, { taaftUrl: taaftUrl(area.taaftQuery || area.area) });
});

// --- 3. Plain-text summary for GHL custom field ---
const topAreasText = topAreas.map(function(a) {
  return '#' + a.rank + '. ' + a.area + '\n' +
    a.why + '\n' +
    'Tools: ' + (a.candidateTools || []).join(', ') + '\n' +
    'Browse: ' + a.taaftUrl;
}).join('\n\n');

// --- 4. HTML report fragment for email embedding ---
function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const areasHtml = topAreas.map(function(a) {
  return '<h3>' + esc(a.rank) + '. ' + esc(a.area) + '</h3>' +
    '<p>' + esc(a.why) + '</p>' +
    '<p><strong>Tools to explore:</strong> ' + esc((a.candidateTools || []).join(', ')) + '</p>' +
    '<p><a href="' + esc(a.taaftUrl) + '">Browse top-rated tools for ' + esc(a.area) + ' &rarr;</a></p>';
}).join('');

const roiFormatted = '$' + Number(webhookBody.annualROI || 0).toLocaleString();

const reportHtml =
  '<h2>' + esc((diagnosis && diagnosis.headline) || 'Your AI Readiness Report') + '</h2>' +
  '<p>' + esc((diagnosis && diagnosis.summary) || '') + '</p>' +
  areasHtml +
  '<hr>' +
  '<p><em>ROI estimate: roughly ' + roiFormatted + '/year in reclaimed time. ' +
  'Treat as directional, not a guarantee.</em></p>';

// --- 5. Return enriched payload (original fields + new report fields) ---
return [
  {
    json: Object.assign({}, webhookBody, {
      assessment_top_areas: topAreasText,
      assessment_tool_suggestions: topAreas.map(function(a) {
        return a.area + ': ' + (a.candidateTools || []).join(', ');
      }).join('\n'),
      assessment_report_html: reportHtml,
      assessment_report_headline: (diagnosis && diagnosis.headline) || '',
      assessment_report_summary: (diagnosis && diagnosis.summary) || ''
    })
  }
];
